import Foundation

/// Places = landmarks / museums / galleries / nature you can visit on a weekday.
/// No stadiums, arenas, concert halls, theatres-as-venues, or malls.
/// Порт `data/FakePlacesRepository.kt`.
enum FakePlacesRepository {
    private static func hoursFor(_ t: String) -> String {
        let l = t.lowercased()
        func has(_ xs: String...) -> Bool { xs.contains { l.contains($0) } }
        if has("монумент", "набережн", "площад", "пл.", "аллея", "бульвар", "парк этно") && !l.contains("байтерек") {
            return "Круглосуточно"
        }
        if l.contains("байтерек") { return "Ежедневно 10:00–21:00" }
        if has("парк", "сад", "ущел", "озеро", "горы") { return "Ежедневно 07:00–23:00" }
        if has("мечеть", "собор", "храм") { return "Ежедневно 05:00–22:00" }
        if has("медеу", "чимбулак", "шымбулак", "кок-тобе", "көктөбе") { return "Ежедневно 10:00–22:00" }
        if has("музей", "дворец", "галере", "экспо", "нур алем") { return "Вт–Вс 10:00–18:00, Пн — выходной" }
        return "Ежедневно 09:00–18:00"
    }

    private static func pl(
        _ c: String, _ n: Int, _ i: Interest, _ title: String, _ address: String,
        _ price: String?, _ url: String, _ source: String,
        kk: String? = nil, en: String? = nil,
        desc: Descriptions.Text? = nil // explicit text for generated city templates
    ) -> EventCard {
        let d = desc ?? Descriptions.forId("place-\(c)-\(n)")
        return EventCard(
            id: "place-\(c)-\(n)", cityId: c,
            titleRu: title, titleKk: kk ?? Translations.kk(title), titleEn: en ?? Translations.en(title),
            startsAt: "",
            placeRu: title, placeKk: kk ?? Translations.kk(title), placeEn: en ?? Translations.en(title),
            address: address, interest: i, price: price,
            whyMatches: "Интерес: \(i.labelRu.lowercased())",
            sourceUrl: url, sourceName: source,
            isPlace: true, workingHours: hoursFor(title),
            descriptionRu: d?.ru ?? "", descriptionKk: d?.kk ?? "", descriptionEn: d?.en ?? ""
        )
    }

    // BEGIN GENERATED by tools/gen_feed.py
    private static func real(
        _ id: String, _ city: String, _ interest: Interest, _ isPlace: Bool,
        _ tRu: String, _ tKk: String, _ tEn: String, _ startsAt: String,
        _ pRu: String, _ pKk: String, _ pEn: String, _ address: String, _ price: String?,
        _ url: String, _ source: String, _ hours: String, _ lat: Double?, _ lon: Double?
    ) -> EventCard {
        let d = Descriptions.forId(id)
        return EventCard(
            id: id, cityId: city, titleRu: tRu, titleKk: tKk, titleEn: tEn, startsAt: startsAt,
            placeRu: pRu, placeKk: pKk, placeEn: pEn, address: address, interest: interest, price: price,
            whyMatches: "Интерес: \(interest.labelRu.lowercased())", sourceUrl: url, sourceName: source,
            isPlace: isPlace, workingHours: hours,
            descriptionRu: d?.ru ?? "", descriptionKk: d?.kk ?? "", descriptionEn: d?.en ?? "",
            lat: lat, lon: lon
        )
    }

