    private static var cache: [String: [EventCard]] = [:]

    private static func template(_ city: City) -> [EventCard] {
        if let hit = cache[city.id] { return hit }
        let c = city.id, n = city.name, k = city.kkName, e = city.latinName
        let list = [
            pl(c, 1, .exhibitions, "Краеведческий музей г. \(n)", "ул. Абая, г. \(n)", "500 ₸", "https://2gis.kz/", "2ГИС",
                kk: "\(k) қаласының өлкетану музейі", en: "\(e) Local History Museum",
                desc: Descriptions.placeTemplate(1, n: n, k: k, e: e)),
            pl(c, 2, .exhibitions, "Городская художественная галерея г. \(n)", "ул. Абая, г. \(n)", "Бесплатно", "https://2gis.kz/", "2ГИС",
                kk: "\(k) қалалық сурет галереясы", en: "\(e) City Art Gallery",
                desc: Descriptions.placeTemplate(2, n: n, k: k, e: e)),
            pl(c, 3, .outdoor, "Центральный парк г. \(n)", "центральный парк, г. \(n)", "Бесплатно", "https://2gis.kz/", "2ГИС",
                kk: "\(k) қаласының орталық саябағы", en: "\(e) Central Park",
                desc: Descriptions.placeTemplate(3, n: n, k: k, e: e)),
            pl(c, 4, .free, "Центральная площадь г. \(n)", "центральная площадь, г. \(n)", "Бесплатно", "https://2gis.kz/", "2ГИС",
                kk: "\(k) қаласының орталық алаңы", en: "\(e) Central Square",
                desc: Descriptions.placeTemplate(4, n: n, k: k, e: e)),
        ]
        cache[city.id] = list
        return list
    }

    static func forCity(_ city: City) -> [EventCard] {
        switch city.id {
        case "astana": return astana
        case "almaty": return almaty
        case "shymkent": return shymkent
        default: return template(city)
        }
    }

    static func forProfile(_ profile: UserProfile, city: City, hidden: Set<String>) -> [EventCard] {
        forCity(city).filter { profile.interests.contains($0.interest) && !hidden.contains($0.id) }
    }
}
